import heapq


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers: dict[str, bool] = {}
        self._tickets: dict[int, dict] = {}
        self._queue: list[tuple[int, int, int]] = []
        self._next_id = 1

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(
        self,
        customer: str,
        title: str,
        priority: str = "normal",
        description: str = "",
    ) -> int:
        if not title:
            raise ValueError("Ticket title cannot be empty")
        if priority not in self.PRIORITIES:
            raise ValueError("Invalid priority")

        vip = self._customers[customer]
        ticket_id = self._next_id
        self._next_id += 1

        key = (0 if vip else 1, -self.PRIORITIES.index(priority), ticket_id)
        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "description": description,
            "key": key,
            "status": "queued",
        }
        heapq.heappush(self._queue, key)
        return ticket_id

    def ticket(self, ticket_id: int) -> dict:
        return self._tickets[ticket_id].copy()

    def tickets_of(self, customer: str) -> list[int]:
        return [
            ticket_id
            for ticket_id, ticket in self._tickets.items()
            if ticket["customer"] == customer
        ]

    def next_ticket(self) -> int | None:
        while self._queue:
            _, _, ticket_id = heapq.heappop(self._queue)
            ticket = self._tickets[ticket_id]
            if ticket["status"] == "queued":
                ticket["status"] = "taken"
                return ticket_id
        return None

    def queue_length(self) -> int:
        return sum(
            ticket["status"] == "queued" for ticket in self._tickets.values()
        )

    def close(self, ticket_id: int) -> None:
        self._tickets[ticket_id]["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        ticket = self._tickets[ticket_id]
        if ticket["status"] == "closed":
            raise ValueError("Cannot reopen a closed ticket")
        if ticket["status"] == "taken":
            ticket["status"] = "queued"
            heapq.heappush(self._queue, ticket["key"])
